import React from 'react';
import { novelStatsData, cultivationSystemData, characterNetworkData } from './staticData';

// 数据加载钩子
export const useDataLoader = <T,>(loadFunction: () => Promise<T>) => {
  const [data, setData] = React.useState<T | null>(null);
  const [loading, setLoading] = React.useState<boolean>(true);
  const [error, setError] = React.useState<Error | null>(null);

  React.useEffect(() => {
    let isMounted = true;
    const fetchData = async () => {
      try {
        setLoading(true);
        console.log('开始加载数据...');
        const result = await loadFunction();
        console.log('数据加载成功:', result);
        
        // 只在组件仍然挂载时更新状态
        if (isMounted) {
          setData(result);
          setError(null);
          setLoading(false);
        }
      } catch (err) {
        console.error('数据加载失败:', err);
        
        // 只在组件仍然挂载时更新状态
        if (isMounted) {
          setError(err instanceof Error ? err : new Error('未知错误'));
          setData(null);
          setLoading(false);
        }
      }
    };

    fetchData();
    
    // 清理函数，防止组件卸载后仍然设置状态
    return () => {
      isMounted = false;
    };
  }, []); // 移除loadFunction依赖，避免无限重新加载

  return { data, loading, error };
};

// 加载小说统计数据 - 直接返回静态数据，不再使用fetch
export const loadNovelStats = async () => {
  console.log('加载小说统计数据 - 使用静态数据');
  
  try {
    // 模拟网络延迟，使UI体验更自然
    await new Promise(resolve => setTimeout(resolve, 300));
    
    // 直接返回静态数据
    console.log('小说统计数据加载成功，数据结构:', Object.keys(novelStatsData));
    return novelStatsData;
  } catch (error) {
    console.error('静态数据加载错误:', error);
    throw new Error('无法加载小说统计数据');
  }
};

